// big disks variant of https://www.shadertoy.com/view/cll3Rj
// minimal variant of  https://shadertoy.com/view/ctlGRj
// golfing 2041 chars "Modular Flow" by mla. https://shadertoy.com/view/dlXGRN

#define hue(v)  ( .6 + .6 * cos( v  + vec4(0,23,21,0)  ) )

void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy, q, V,I,
         U =   ( 8.* ( u+u - R ) / R.y  + 2. )                         // normalized coords
             * mat2(cos( .1*iTime + vec4(0,33,11,0)))                  // rotation
             - 2.;
    float w = 16./R.y,                                                 // pixel width, for AA

          k = exp( log(2.618)* fract(iTime/4.) - .5 );                 // --- the heart of the transform
    mat2  P = mat2( vec2(1,-1.618) / 1.9 ,                             // ( see mla original : https://shadertoy.com/view/dlXGRN )
                    vec2(1,  .618) / 1.176 );                          // NB: P is orthonormal ( i.e. rotation )
    q = vec2(k,1./k);                                                  // volume conservative shear. k: .6 → .92
    V = P * ( U * q );                                                 // shear and rotate up to the next shear axis

    O *= 0.;
    for( int i=0; i<9; i++ )                                           // visit neighborhood to complete disk footprint (shouldn't 4 be enough ? )
        I = round(V) + vec2(i%3,i/3) - 1.,                             // neighbor Id. V-I = local coord
        O += smoothstep( w, -w,  length( ( V - I ) * P / q ) - .48 )   // draw disks via back-transform
             * ( iMouse.z>0. ? hue( ( I.x+17.*I.y)/12. ) : vec4(1) );  // mouse: color disks
          // * ( ( mod(I.x+I.y,2.) < 1. ) ? .5 : 1. ) ;                // checker
     // O += sin( 30. * length( ( V - round(V) ) * P / q ) ) -O;       
     // O += .05/ dot( u = ( V - I ) * P / q , u );

  // O = sin(30.*O);
}
